R,C=len(D2),len(D2[0]); dirs=[(1,0),(-1,0),(0,1),(0,-1)]
def dist_path(grid, path, source_coords_by_label):
    ds={lab:[[10**6]*C for _ in range(R)] for lab in source_coords_by_label}
    for lab, coords in source_coords_by_label.items():
        q=deque()
        for rr,cc in coords:
            for dr,dc in dirs:
                r,c=rr+dr,cc+dc
                if 0<=r<R and 0<=c<C and grid[r][c]==path and ds[lab][r][c]>1:
                    ds[lab][r][c]=1;q.append((r,c))
        while q:
            r,c=q.popleft()
            for dr,dc in dirs:
                nr,nc=r+dr,c+dc
                if 0<=nr<R and 0<=nc<C and grid[nr][nc]==path and ds[lab][nr][nc]>ds[lab][r][c]+1:
                    ds[lab][nr][nc]=ds[lab][r][c]+1;q.append((nr,nc))
    pred=[]
    for r in range(R):
        row=[]
        for c in range(C):
            if grid[r][c]!=path: row.append(grid[r][c]); continue
            d={lab:dist[r][c] for lab,dist in ds.items()}
            md=min(d.values()); labs=[lab for lab,v in d.items() if v==md]
            row.append(labs[0] if md<10**6 and len(labs)==1 else path)
        pred.append(row)
    return pred, ds
